"""Fixed operator hotfix, then one verified scheduled backup. No product restart."""
import base64
import fcntl
import hashlib
import json
import os
from pathlib import Path
import stat
import sqlite3
from contextlib import closing
import subprocess
import tempfile
import uuid

OLD='fab31d283971b3d36d3cf4c4f480f36e32e16f7f5a627ebbd422ec9741d31288'
NEW='c18bfafecbefb136d0d5bca0b0994c373629708d19c100040b383e673edc697c'
PAYLOAD=''
CHECKER='8d887e14588d8f9b5fe1b164678aef0feb24fd5b2288ffcec1d6da4d062ceab5'
WORKERS=(Path('/opt/authwire-backup/scheduled_backup.py'),Path('/opt/kaname-lab/source/tools/scheduled_backup.py'))
RELEASE=Path('/opt/authwire-backup/release.json')
UNITS=('kaname-lab.service','authwire-radius.service','authwire-service-control.service')

def sha(data):return hashlib.sha256(data).hexdigest()
def require(value,code):
    if not value:raise ValueError(code)
def read(path):
    for parent in (path.parent,*path.parent.parents):
        info=parent.lstat()
        require(stat.S_ISDIR(info.st_mode) and info.st_uid==0 and not info.st_mode&0o022,'UNSAFE_PARENT')
    info=path.lstat()
    require(stat.S_ISREG(info.st_mode) and info.st_uid==0 and not info.st_mode&0o022,'UNSAFE_FILE')
    require(info.st_size<=262144,'FILE_LIMIT')
    return path.read_bytes(),info
def atomic(path,data,info=None,mode=0o600):
    fd,name=tempfile.mkstemp(prefix='.backup-poll-fix-',dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as stream:
            os.fchmod(stream.fileno(),stat.S_IMODE(info.st_mode) if info else mode)
            if info:os.fchown(stream.fileno(),info.st_uid,info.st_gid)
            stream.write(data);stream.flush();os.fsync(stream.fileno())
        os.replace(name,path)
        directory=os.open(path.parent,os.O_RDONLY|os.O_DIRECTORY)
        try:os.fsync(directory)
        finally:os.close(directory)
    finally:
        Path(name).unlink(missing_ok=True)
def pids():
    return {unit:subprocess.check_output(['systemctl','show',unit,'--property=MainPID','--value'],text=True,timeout=10).strip() for unit in UNITS}
def main():
    require(os.geteuid()==0,'OPERATOR_SUDO_REQUIRED')
    payload=base64.b64decode(PAYLOAD,validate=True)
    require(sha(payload)==NEW,'PAYLOAD_CHANGED');compile(payload,'scheduled_backup.py','exec')
    lock=Path('/run/kaname-lab-update.lock');_,lock_info=read(lock)
    fd=os.open(lock,os.O_RDWR|os.O_NOFOLLOW)
    evidence=None
    try:
        fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
        require(subprocess.check_output(['systemctl','show','authwire-backup.service','--property=ActiveState','--value'],text=True,timeout=10).strip() not in ('active','activating','deactivating'),'BACKUP_ALREADY_RUNNING')
        before=pids();values={p:read(p) for p in (*WORKERS,RELEASE)}
        checker,_=read(Path('/opt/authwire-backup/offline_restore_check.py'))
        require(sha(checker)==CHECKER,'RESTORE_CHECKER_CHANGED')
        release=json.loads(values[RELEASE][0])
        require(set(release)=={'scheduled_backup.py','offline_restore_check.py'} and release['offline_restore_check.py']==CHECKER,'RELEASE_CHANGED')
        already=all(sha(values[p][0])==NEW for p in WORKERS) and release['scheduled_backup.py']==NEW
        require(already or (all(sha(values[p][0])==OLD for p in WORKERS) and release['scheduled_backup.py']==OLD),'WORKER_BASELINE_CHANGED')
        if not already:
            root=Path('/var/lib/authwire-updates');root.mkdir(mode=0o700,exist_ok=True)
            require(root.lstat().st_uid==0 and not root.lstat().st_mode&0o022 and not root.is_symlink(),'EVIDENCE_ROOT_UNSAFE')
            evidence=root/('backup-poll-fix-r2-20261028-'+uuid.uuid4().hex);evidence.mkdir(mode=0o700)
            for index,(path,(raw,info)) in enumerate(values.items()):atomic(evidence/('before-'+str(index)),raw)
            changed=[]
            try:
                for path in WORKERS:
                    require(sha(read(path)[0])==OLD,'SOURCE_CHANGED_DURING_PREPARATION')
                    atomic(path,payload,values[path][1]);changed.append(path)
                new_release=dict(release);new_release['scheduled_backup.py']=NEW
                require(read(RELEASE)[0]==values[RELEASE][0],'RELEASE_CHANGED_DURING_PREPARATION')
                atomic(RELEASE,(json.dumps(new_release,sort_keys=True,indent=2)+'\n').encode(),values[RELEASE][1]);changed.append(RELEASE)
                require(all(sha(read(p)[0])==NEW for p in WORKERS) and pids()==before,'POSTCHECK_FAILED')
            except Exception:
                for path in reversed(changed):
                    expected=NEW if path in WORKERS else sha((json.dumps(new_release,sort_keys=True,indent=2)+'\n').encode())
                    if sha(read(path)[0])==expected:atomic(path,values[path][0],values[path][1])
                raise
        require(pids()==before,'PRODUCT_PROCESS_CHANGED')
        summary={'event':'BACKUP_POLL_FIX_SOURCE_VERIFIED','updated':not already,'worker_sha256':NEW,'evidence':str(evidence) if evidence else None,'product_processes_preserved':True,'database_changed':False,'units_changed':False,'restore_checker_changed':False}
        if evidence:atomic(evidence/'summary.json',(json.dumps(summary,indent=2)+'\n').encode())
        print(json.dumps(summary),flush=True)
    finally:os.close(fd)
    namespace={'__name__':'authwire_backup_reviewed_worker'}
    exec(compile(payload,'reviewed-backup-worker','exec'),namespace)
    with closing(sqlite3.connect('file:/var/lib/kaname-lab/kaname.sqlite3?mode=ro',uri=True,timeout=3)) as db:
        db.execute('PRAGMA query_only=ON');db.execute('BEGIN')
        checked=[]
        for name in sorted(namespace['POLL_SECTIONS']):
            row=db.execute('SELECT payload FROM runtime_settings WHERE name=?',(name,)).fetchone()
            if row is None:continue
            projected=namespace['stable_runtime_payload'](name,row[0])
            recognized=projected!=row[0]
            checked.append({'name':name,'recognized':recognized})
        print(json.dumps({'event':'BACKUP_POLL_FORMAT_CHECK','queues':checked,'database_writes':False,'secret_values_exported':False}),flush=True)
        require(all(item['recognized'] for item in checked),'LIVE_QUEUE_FORMAT_NOT_RECOGNIZED')
    print(json.dumps({'event':'VERIFIED_BACKUP_STARTING','product_services_restarted':False}),flush=True)
    result=subprocess.run(['systemctl','start','authwire-backup.service'],timeout=660)
    status=json.loads(Path('/var/backups/authwire/scheduled/last-run.json').read_bytes())
    print(json.dumps(status),flush=True)
    require(result.returncode==0 and status.get('event')=='BACKUP_SUCCESS','BACKUP_NOT_SUCCESSFUL')
    archive=Path(status['backup'])
    h=hashlib.sha256()
    with archive.open('rb') as stream:
        for block in iter(lambda:stream.read(1048576),b''):h.update(block)
    require(h.hexdigest()==status['sha256'],'BACKUP_ARCHIVE_HASH_MISMATCH')
    print(json.dumps({'event':'BACKUP_POLL_FIX_FINISHED','backup':str(archive),'sha256':status['sha256'],'archive_sha256_verified':True,'product_processes_preserved':pids()==before,'full_appliance_boot_restore_tested':False}),flush=True)

if __name__=='__main__':
    try:main()
    except Exception as error:
        print(json.dumps({'event':'BACKUP_POLL_FIX_FAILED','category':type(error).__name__,'reason':str(error)[:160]}),flush=True)
        raise SystemExit(1)
